// Isolation test (OS-12) — construct InvalidationLedger with its declared inputs and nothing
// else, then exercise every public operation. (Generated by new-object.py, rewritten for
// strict TypeScript - MF-21.)
import { describe, expect, it } from "vitest";
import { isUnknown } from "../src/kernel/index.js";
import type { RendererPort } from "../src/ports/index.js";
import type { Currency, Unit } from "../src/catalog/index.js";
import { LineageReader } from "../src/facts/index.js";
import { InvalidationLedger, InvalidationScope, type ScopeValue } from "../src/lineage/index.js";
import { inMemoryRecord } from "./catalog/in-memory-record.js";
import { factWorld, never } from "./support/fact-world.js";

const u = "u1" as Unit;
const [c0, c1] = ["c0", "c1"] as unknown as readonly [Currency, Currency];
const quiet: RendererPort<ScopeValue> = { present: () => undefined };

/** A record where u committed at c0 and drew one candidate from it. */
function world() {
  const w = factWorld({ currencies: ["c0", "c1"], invalidations: never });
  const k0 = w.commitAt(u, c0);
  w.drawAt(u, c1);
  const scopes = new InvalidationScope({ lineage: new LineageReader({ record: w.record }) });
  return { ...w, k0, scopes };
}

describe("InvalidationLedger in isolation", () => {
  it("refuses to construct when an input is missing", () => {
    const w = world();
    expect(() => new InvalidationLedger({ scopes: w.scopes, renderer: quiet } as never)).toThrow();
    expect(() => new InvalidationLedger({ record: w.record, renderer: quiet } as never)).toThrow();
    expect(() => new InvalidationLedger({ record: w.record, scopes: w.scopes } as never)).toThrow();
  });

  it("refuses inputs that do not offer the operations it calls (OS-1, declared slots)", () => {
    const w = world();
    expect(() => new InvalidationLedger({ record: {} as never, scopes: w.scopes, renderer: quiet })).toThrow();
    expect(() => new InvalidationLedger({ record: w.record, scopes: {} as never, renderer: quiet })).toThrow();
    expect(() => new InvalidationLedger({ record: w.record, scopes: w.scopes, renderer: {} as never })).toThrow();
  });

  it("display answers differently when scopes differs", () => {
    const w = world();
    const h = w.record.noise();
    const empty = new InvalidationScope({ lineage: new LineageReader({ record: inMemoryRecord() }) });
    const a = new InvalidationLedger({ record: w.record, scopes: w.scopes, renderer: quiet }).display(w.k0, h);
    const b = new InvalidationLedger({ record: w.record, scopes: empty, renderer: quiet }).display(w.k0, h);
    expect(a).not.toEqual(b);
  });

  it("display hands the scope to the renderer it was given (its answer is never read, OBJ-36)", () => {
    const w = world();
    const h = w.record.noise();
    const seen: string[] = [];
    new InvalidationLedger({ record: w.record, scopes: w.scopes, renderer: { present: () => void seen.push("first") } }).display(w.k0, h);
    new InvalidationLedger({ record: w.record, scopes: w.scopes, renderer: { present: () => void seen.push("second") } }).display(w.k0, h);
    expect(seen).toEqual(["first", "second"]);
  });

  it("invalidate answers differently when record differs", () => {
    const w = world();
    const busy = inMemoryRecord();
    busy.noise();
    const h = w.record.noise();
    const shown = new InvalidationLedger({ record: w.record, scopes: w.scopes, renderer: quiet }).display(w.k0, h);
    const a = new InvalidationLedger({ record: w.record, scopes: w.scopes, renderer: quiet }).invalidate(shown, "HUMAN", h);
    const b = new InvalidationLedger({ record: busy, scopes: w.scopes, renderer: quiet }).invalidate(shown, "HUMAN", h);
    expect(a).not.toEqual(b);
  });

  it("isInvalidated answers differently when record differs", () => {
    const w = world();
    const ledger = new InvalidationLedger({ record: w.record, scopes: w.scopes, renderer: quiet });
    const h = w.record.noise();
    const inv = ledger.invalidate(ledger.display(w.k0, h), "HUMAN", h);
    if (isUnknown(inv)) throw new Error("setup: the invalidation was refused");
    const elsewhere = new InvalidationLedger({ record: inMemoryRecord(), scopes: w.scopes, renderer: quiet });
    expect(ledger.isInvalidated(w.k0, inv.at)).not.toEqual(elsewhere.isInvalidated(w.k0, inv.at));
  });

  it("invalidatedAsOf answers differently when record differs", () => {
    const w = world();
    const ledger = new InvalidationLedger({ record: w.record, scopes: w.scopes, renderer: quiet });
    const h = w.record.noise();
    const inv = ledger.invalidate(ledger.display(w.k0, h), "HUMAN", h);
    if (isUnknown(inv)) throw new Error("setup: the invalidation was refused");
    const elsewhere = new InvalidationLedger({ record: inMemoryRecord(), scopes: w.scopes, renderer: quiet });
    expect(ledger.invalidatedAsOf(inv.at)).not.toEqual(elsewhere.invalidatedAsOf(inv.at));
  });
});
